import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Transaction } from '../../shared/Transictions/Transaction'; 
import { TransactionService } from '../../services/transaction.service';
import { AuthService } from '../../services/auth.service';
import { TransactionCardComponent } from '../transation/transation'; // Seu componente de card

@Component({
  selector: 'app-transaction-list',
  standalone: true,
  // IMPORTANTE: Importar o CommonModule (*ngIf, *ngFor) e o componente filho
  imports: [CommonModule, TransactionCardComponent], 
  templateUrl: './transaction-list.component.html', // Aponta para o template abaixo
  styleUrls: ['./transaction-list.component.css']
})
export class TransactionListComponent implements OnInit {
  
  // Variáveis de estado e dados
  transactions: Transaction[] = []; // Inicializado como array vazio
  isLoading: boolean = true;
  errorMessage: string = '';

  constructor(
    private transactionService: TransactionService,
    private authService: AuthService // Injetando o serviço para obter o ID
  ) {}

  ngOnInit(): void {
    this.loadTransactions();
  }

  loadTransactions(): void {
    const userId = this.authService.getUserId();

    if (!userId) {
      this.errorMessage = 'Usuário não autenticado. Por favor, faça login.';
      this.isLoading = false;
      return;
    }

    this.isLoading = true;
    this.errorMessage = '';

    // Busca os dados da API
    this.transactionService.fetch<Transaction[]>(userId).subscribe({
      next: (data) => {
        // Sucesso: armazena os dados e desativa o loading
        this.transactions = data;
        this.isLoading = false;
      },
      error: (err) => {
        // Erro: exibe mensagem e desativa o loading
        console.error('Erro ao carregar transações:', err);
        this.errorMessage = 'Falha na comunicação com a API.';
        this.isLoading = false;
      }
    });
  }
}
